            amenity = bench
            or amenity = lounger
            or amenity = waste_basket
            or amenity = recycling and recycling_type = container
            or amenity = toilets
            or amenity = shower
            or amenity = drinking_water
            or man_made = planter
          )
          and (${lastChecked(6.0)})
        ) or (
          (
            amenity ~ bicycle_parking|motorcycle_parking|taxi|shelter
          )
